import {skillInfo} from './insight-ui.mjs';
import {items,shopItems,itemMeta,slots,itemCount,recipesFor,canUseItem} from './workshop.mjs';
import {lessonsFor} from './market.mjs';
import {abilities} from './combat.mjs';
const button=(id,label,disabled)=>`<button class="catalog-action" data-choice="${id}" ${disabled?'disabled':''}>${label}</button>`;
export function marketPanel(s){const j=s.journey;if(!j)return '';
 if(s.scene==='shop')return `<div class="catalog-tabs"><button class="catalog-filter active" data-filter="all">전체</button><button class="catalog-filter" data-filter="equipment">장비</button><button class="catalog-filter" data-filter="consumable">소모품</button></div><div class="item-grid">${shopItems(s).map(i=>{const owned=itemCount(j,i.id)>0&&i.type==='equipment';return `<article class="item-card" data-item-type="${i.type}"><div class="item-icon">${i.icon}</div><div class="item-copy"><small>${itemMeta(i)}</small><h3>${i.name}</h3><p>${i.description}</p><span>코인 ${i.price} · 보유 ${itemCount(j,i.id)}</span></div>${button('buy-item-'+i.id,owned?'구입 완료':j.gold<i.price?'코인 부족':'구입하기',owned||j.gold<i.price)}</article>`;}).join('')}</div>`;
 if(s.scene==='bag')return `<div class="equipment-slots">${Object.entries(slots).map(([id,label])=>`<div><small>${label}</small><strong>${items.find(i=>i.id===j.equipped[id])?.name||'장착 없음'}</strong></div>`).join('')}</div>${Object.keys(j.prepBuffs).length?`<div class="prepared-buffs">다음 전투 준비: ${Object.entries(j.prepBuffs).map(([k,v])=>({attack:'위력',speed:'속도',shield:'보호막'}[k])+' +'+v).join(' · ')}</div>`:''}<div class="item-grid">${items.filter(i=>itemCount(j,i.id)>0).map(i=>`<article class="item-card"><div class="item-icon">${i.icon}</div><div class="item-copy"><small>${itemMeta(i)}</small><h3>${i.name}</h3><p>${i.description}</p></div>${button((i.type==='equipment'?'equip-item-':'use-item-')+i.id,i.type==='equipment'?(j.equipped[i.slot]===i.id?'장착 해제':'장착하기'):'사용하기',i.type==='consumable'&&!canUseItem(s,i))}</article>`).join('')}</div>`;
 if(s.scene==='school')return `<p class="lesson-heading">등급 ${j.level} · 이번 가르침 ${lessonsFor(s).length}개</p><div class="art-grid">${lessonsFor(s).map(a=>`<article class="art-card"><p class="eyebrow">${a.innate?'고유 능력':a.passive?'능력':a.kind+' · 숨 '+a.cost}</p><h3>${a.name}${a.upgrade?' 강화':''}</h3><p>${a.description}</p><details class="skill-math"><summary>수치 상세</summary>${skillInfo(s,a)}</details><small>${a.requirement} · 코인 ${a.price}</small>${button('learn-'+a.id,a.bought?'수련 완료':j.gold<a.price?'코인 부족':a.upgrade?'기술 강화':'기술 익히기',a.bought||j.gold<a.price)}</article>`).join('')}</div>`;

 if(s.scene==='synthesis'){const known=abilities(s).map(a=>a.id),ready=recipesFor(s).filter(a=>!j.learned.includes(a.id)&&a.ingredients.every(id=>known.includes(id))),other=recipesFor(s).filter(a=>!ready.some(r=>r.id===a.id));
 const card=a=>{const learned=j.learned.includes(a.id),missing=a.ingredients.some(id=>!known.includes(id));return `<article class="recipe-card ${learned?'learned':''}"><div class="recipe-inputs">${a.labels.map((name,i)=>`<span class="${known.includes(a.ingredients[i])?'known':''}">${known.includes(a.ingredients[i])?'✓ ':''}${name}</span>`).join('<b>＋</b>')}</div><div class="recipe-arrow">↓</div><p class="eyebrow">${a.kind} · 숨 ${a.cost}</p><h3>${a.name}</h3><p>${a.description}</p>${skillInfo(s,{...a,rank:j.skillRanks[a.id]||0})}<small>코인 ${a.gold} · 강화석 ${a.ore}</small>${button('combine-'+a.id,learned?'습득 완료':missing?'재료 기술 필요':j.gold<a.gold||j.ore<a.ore?'재화 부족':'이 기술 익히기',learned||missing||j.gold<a.gold||j.ore<a.ore)}</article>`;};
 return `${ready.length?'<p class="muted">지금 배운 기술로 이어갈 수 있는 조합입니다.</p>':'<p class="empty-skills">아직 이어 붙일 기술이 부족합니다. 먼저 가르침을 하나씩 익혀 보세요.</p>'}<div class="recipe-grid">${ready.map(card).join('')}</div>${other.length?`<details class="other-recipes"><summary>다른 조합의 재료 보기</summary><div class="recipe-grid">${other.map(card).join('')}</div></details>`:''}`;}

 return '';
}
